MC(s,('6۔ ثَلَاثُونَ شَهْرًا کے معنی ہیں:','6. “Thalāthūna shahran” means:','۶. «ثلاثون شهرا» معنا ده:'),[('بیس ماہ','twenty months','شل میاشتې'),('تیس ماہ','thirty months','دېرش میاشتې'),('چالیس ماہ','forty months','څلوېښت میاشتې'),('پچاس ماہ','fifty months','پنځوس میاشتې')])
